window.GRILE_QUESTION_SHARDS=window.GRILE_QUESTION_SHARDS||{};window.GRILE_QUESTION_SHARDS["shard-93"]=[{"id":"set2-AlLdUjGD","fingerprint":"cd8e27ecdb67bf1e","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt obiectivele principale ale tratamentului cariei simple?","options":[{"id":"A","text":"Oprirea în evoluție a leziunilor de la nivelul țesuturilor dure dentare, precum smalțul și dentina."},{"id":"B","text":"Refacerea morfofuncțională a dintelui afectat de procesul carios."},{"id":"C","text":"Prevenirea complicațiilor care pot afecta pulpa dentară sau parodonțiul."},{"id":"D","text":"Reducerea incidenței tuturor afecțiunilor orale prin profilaxie generală."},{"id":"E","text":"Aplicarea exclusivă a tehnicilor de restaurare directă pentru refacerea morfofuncțională."}],"correct":["A","C"],"pages":[59],"source":"set-2"},{"id":"set2-0j0kVONx","fingerprint":"4c640ad166e5ef84","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce tip de abordare terapeutică este indicată în cazul leziunilor cavitare, caracterizate prin lipsă de substanță dură dentară?","options":[{"id":"A","text":"O abordare terapeutică operatorie convențională (invazivă)."},{"id":"B","text":"Utilizarea exclusivă a modalităților de cariodetecție fără intervenție restauratoare."},{"id":"C","text":"Amânarea tratamentului pentru a evalua progresia leziunii."},{"id":"D","text":"O abordare terapeutică neconvențională, de tip neinvaziv sau minim invaziv."},{"id":"E","text":"Tratamentul restaurator prin tehnici semidirecte ca unică opțiune."}],"correct":["A"],"pages":[59],"source":"set-2"},{"id":"set2-tW7HXeZv","fingerprint":"6a08a23e02abe5be","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt fazele tratamentului convențional al cariei simple?","options":[{"id":"A","text":"Faza de diagnostic și planificare."},{"id":"B","text":"Faza de tratament medicamentos."},{"id":"C","text":"Faza de tratament chirurgical."},{"id":"D","text":"Faza de tratament restaurator."},{"id":"E","text":"Faza de profilaxie."}],"correct":["B","C","D"],"pages":[59],"source":"set-2"},{"id":"set2-bCNWHohz","fingerprint":"dbed8579fa5998e6","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce urmărește în principal faza de tratament medicamentos în cadrul tratamentului cariei simple?","options":[{"id":"A","text":"Realizarea protecției dentino-pulpare prin tratamentul plăgii dentinare."},{"id":"B","text":"Îndepărtarea țesuturilor dure dentare alterate ireversibil de procesul carios."},{"id":"C","text":"Crearea unei preparații care să permită inserarea și menținerea restaurării."},{"id":"D","text":"Prevenirea recidivelor prin plasarea conservatoare a limitelor preparației."},{"id":"E","text":"Refacerea morfofuncțională a dintelui prin tehnici directe, semidirecte sau indirecte."}],"correct":["A"],"pages":[59],"source":"set-2"},{"id":"set2-mrx8Vv-e","fingerprint":"50b9f2dd263ebe35","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele afirmații descriu corect obiectivele preparării cavităților?","options":[{"id":"A","text":"Plasarea limitelor preparației cât mai conservator posibil pentru a preveni apariția cariei secundare marginale."},{"id":"B","text":"Conformarea preparației astfel încât forțele ocluzale să nu producă fractura dintelui sau a restaurării, ori dizlocarea acesteia."},{"id":"C","text":"Extinderea profilactică a limitelor preparației în toate șanțurile și fosetele adiacente."},{"id":"D","text":"Crearea condițiilor necesare doar pentru inserarea materialului de restaurare."},{"id":"E","text":"Îndepărtarea substanței dure dentare alterate ireversibil, cu protejarea corespunzătoare a organului pulpar."}],"correct":["A","B","E"],"pages":[59],"source":"set-2"},{"id":"set2-Xt1xKt1v","fingerprint":"2d413d0fe65bb10a","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care sunt factorii care condiționează efectuarea preparației unei cavități?","options":[{"id":"A","text":"Exclusiv prezența sau absența unei leziuni cavitare."},{"id":"B","text":"Tipul de restaurare morfofuncțională (materiale și tehnici) și structurile odontale implicate."},{"id":"C","text":"Fazele de tratament medicamentos și restaurator care vor urma."},{"id":"D","text":"Doar principiile de biocompatibilitate, funcționalitate și estetică."},{"id":"E","text":"Gradul de evoluție al leziunii și prezența complicațiilor pulpare."}],"correct":["B"],"pages":[59],"source":"set-2"},{"id":"set2-ir8XbQ-Y","fingerprint":"455f0bbdd3804682","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următorii factori condiționează efectuarea unei preparații dentare?","options":[{"id":"A","text":"Structurile dento-maxilare corelate, cum ar fi dinții adiacenți și antagoniști"},{"id":"B","text":"Vârsta și starea de sănătate sistemică a pacientului"},{"id":"C","text":"Structurile odontale implicate, precum organul pulpar și parodonțiul marginal superficial"},{"id":"D","text":"Tipul de restaurare morfofuncțională (materiale și tehnici)"},{"id":"E","text":"Preferințele exclusive ale operatorului, indiferent de dotările disponibile"}],"correct":["A","B","C","D"],"pages":[60],"source":"set-2"},{"id":"set2-IQzZ1hbE","fingerprint":"e1a706cf14313d37","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt localizările specifice pentru o cavitate de clasa I?","options":[{"id":"A","text":"Fosetele supracingulare, pe fețele palatinale ale frontalilor superiori."},{"id":"B","text":"Șanțurile și fosetele ocluzale la molari și premolari."},{"id":"C","text":"Treimea cervicală a fețelor vestibulare și orale ale tuturor dinților."},{"id":"D","text":"Șanțurile și fosetele vestibulare/orale la molari."},{"id":"E","text":"Fețele proximale ale molarilor și premolarilor."}],"correct":["A","B","D"],"pages":[60],"source":"set-2"},{"id":"set2--xxca_Ts","fingerprint":"1d3e9239a537f2d9","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce element clinic diferențiază fundamental o cavitate de clasa a III-a de una de clasa a IV-a?","options":[{"id":"A","text":"Extinderea leziunii în treimea cervicală."},{"id":"B","text":"Localizarea pe fața proximală versus fața ocluzală."},{"id":"C","text":"Integritatea unghiului incizal."},{"id":"D","text":"Tipul de dinte afectat, clasa a III-a fiind la frontali și clasa a IV-a la premolari."},{"id":"E","text":"Prezența sau absența contactului cu dintele adiacent."}],"correct":["C"],"pages":[60],"source":"set-2"},{"id":"set2--TMrOPEq","fingerprint":"13cabb9b05780fec","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"O leziune carioasă care afectează exclusiv vârful unui cuspid la un premolar corespunde unei cavități de clasa:","options":[{"id":"A","text":"a II-a"},{"id":"B","text":"a IV-a"},{"id":"C","text":"a VI-a"},{"id":"D","text":"a V-a"},{"id":"E","text":"a I-a"}],"correct":["C"],"pages":[60],"source":"set-2"},{"id":"set2-lcIkgBNf","fingerprint":"eb43e4a72ebcfcb2","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt obiectivele principale ale preparării unei cavități, conform definiției clasice?","options":[{"id":"A","text":"Restaurarea formei coronare inițiale și împiedicarea reapariției procesului carios."},{"id":"B","text":"Îndepărtarea leziunilor carioase și asigurarea rezistenței restaurării."},{"id":"C","text":"Crearea unui spațiu cât mai mare pentru a facilita inserarea materialului de obturație."},{"id":"D","text":"Modificarea culorii dintelui pentru a se potrivi cu restaurarea."},{"id":"E","text":"Sterilizarea completă a organului pulpar."}],"correct":["A","B"],"pages":[60],"source":"set-2"},{"id":"set2-nykv08n4","fingerprint":"0ef41bcd4e88afa1","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"În cadrul clasificării leziunilor în funcție de localizare (Site) și dimensiune (Size), ce zone anatomice sunt incluse în categoria Site 1?","options":[{"id":"A","text":"Zona supracingulară la dinții frontali superiori."},{"id":"B","text":"Suprafețele cu șanțuri și fosete ale dinților laterali."},{"id":"C","text":"Zona cervicală a dinților și suprafața radiculară."},{"id":"D","text":"Fețele proximale ale dinților frontali și laterali."},{"id":"E","text":"Vârfurile cuspidiene la dinții laterali."}],"correct":["A","B","E"],"pages":[60],"source":"set-2"},{"id":"set2-D5DnAz9C","fingerprint":"64d6059ac63e6c60","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce caracterizează o leziune carioasă de tip Size 0 (incipientă) și care este tratamentul indicat?","options":[{"id":"A","text":"Este o leziune cavitară minimă, cu afectarea stratului extern al dentinei, necesitând un tratament minim invaziv."},{"id":"B","text":"Este o leziune cavitară cu afectare profundă a dentinei."},{"id":"C","text":"Este o leziune de demineralizare, superficială, necavitară, al cărei tratament este neinvaziv (remineralizare)."},{"id":"D","text":"Este o leziune cavitară cu afectarea dentinei în treimea medie."},{"id":"E","text":"Este o leziune cu distrucție coronară extinsă."}],"correct":["C"],"pages":[60],"source":"set-2"},{"id":"set2-7wuXB-Z4","fingerprint":"49c63a34746a0b52","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"O leziune carioasă localizată pe fața proximală a unui premolar, care a produs o cavitate cu afectarea profundă a dentinei, corespunde cărei clasificări în funcție de localizare (Site) și dimensiune (Size)?","options":[{"id":"A","text":"Site 2, Size (extinsă)"},{"id":"B","text":"Site 2, Size 4"},{"id":"C","text":"Site 3, Size 4"},{"id":"D","text":"Site 1, Size 4"},{"id":"E","text":"Site 2, Size 3"}],"correct":["B"],"pages":[60],"source":"set-2"},{"id":"set2-wWHqaojB","fingerprint":"bd1c5d088173957c","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt obiectivele principale ale etapei de deschidere a procesului carios în prepararea unei cavități?","options":[{"id":"A","text":"Evidențierea extinderii leziunii carioase și asigurarea accesului pentru manoperele ulterioare."},{"id":"B","text":"Protejarea pulpei dentare prin limitarea profunzimii preparației inițiale."},{"id":"C","text":"Îndepărtarea în totalitate a dentinei alterate de pe pereții cavității."},{"id":"D","text":"Crearea unei forme geometrice, de tip \"box like\", pentru a asigura retenția obturației."},{"id":"E","text":"Accesul pentru instrumente și vizibilitatea asupra extinderii leziunii."}],"correct":["A","E"],"pages":[61],"source":"set-2"},{"id":"set2-FSWnGoWI","fingerprint":"e05c87a48ed69dc9","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele afirmații despre căile de acces în prepararea cavităților sunt corecte?","options":[{"id":"A","text":"La cavitățile de clasa a II-a cu creasta marginală întreruptă, accesul este direct."},{"id":"B","text":"Accesul direct în cazul cariilor proximale de clasa a III-a este posibil doar dacă dintele vecin lipsește."},{"id":"C","text":"În cazul cariilor de clasa a III-a, accesul indirect se realizează de preferat dinspre oral."},{"id":"D","text":"La toate cavitățile de clasa a II-a, este obligatorie etapa de ușurare a accesului."},{"id":"E","text":"Pentru leziunile de clasa I cu orificiu mic de deschidere, este necesară etapa de ușurare a accesului."}],"correct":["A","C","E"],"pages":[61],"source":"set-2"},{"id":"set2-D5M-d5_M","fingerprint":"940988215642b23f","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"În ce context este acceptată păstrarea dentinei dure, dar pigmentate, în timpul exerezei țesutului alterat?","options":[{"id":"A","text":"În cavitățile de adâncime medie, pentru a evita transformarea lor în cavități profunde."},{"id":"B","text":"În orice tip de cavitate, dacă pacientul este tânăr și nu are antecedente de durere."},{"id":"C","text":"În cavitățile profunde, pe podeaua cavității."},{"id":"D","text":"Doar la nivelul pereților laterali ai cavității, fiind interzisă păstrarea ei pe podeaua cavității."},{"id":"E","text":"În cavitățile superficiale, pentru a menține un strat de protecție suplimentar pentru pulpă."}],"correct":["A","C"],"pages":[61],"source":"set-2"},{"id":"set2-AAQhS-en","fingerprint":"19f8af3632eeddc7","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt condițiile cumulative necesare pentru a se putea păstra zone punctiforme de dentină alterată în cavitățile profunde?","options":[{"id":"A","text":"Dintele în cauză nu are un istoric de simptomatologie specifică inflamației pulpare."},{"id":"B","text":"Ulterior se va realiza un tratament de coafaj indirect în doi timpi."},{"id":"C","text":"Pacientul este tânăr și sănătos clinic."},{"id":"D","text":"Accesul în cavitate este indirect, pentru a limita vizibilitatea asupra coarnelor pulpare."},{"id":"E","text":"Există un acces direct în cavitate care facilitează manoperele terapeutice."}],"correct":["A","B","C","E"],"pages":[61],"source":"set-2"},{"id":"set2-NLYurbmK","fingerprint":"3635efc54a45ed41","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce recomandări specifice se fac în privința instrumentarului utilizat pentru exereza dentinei alterate?","options":[{"id":"A","text":"Se preferă instrumentarul manual, precum lingurile Black sau excavatoarele, bine ascuțite."},{"id":"B","text":"Instrumentarul rotativ este evitat deoarece produce căldură și vibrații nocive pentru pulpa dentară."},{"id":"C","text":"Se recomandă utilizarea instrumentarului manual și rotativ în egală măsură, alegerea fiind la latitudinea medicului."},{"id":"D","text":"Instrumentarul rotativ este indicat pentru a îndepărta rapid dentina alterată fără a produce presiuni."},{"id":"E","text":"Instrumentele trebuie să fie neascuțite pentru a nu exercita presiuni excesive asupra podelei cavității."}],"correct":["A","B"],"pages":[61],"source":"set-2"},{"id":"set2-dPhj9bi4","fingerprint":"4a2af2bd757e61d0","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt recomandările corecte privind exereza dentinei alterate?","options":[{"id":"A","text":"Se preferă utilizarea instrumentelor manuale, precum lingurile Black, pentru a proteja pulpa dentară."},{"id":"B","text":"Îndepărtarea dentinei alterate trebuie să înceapă de pe peretele pulpar pentru a evalua profunzimea leziunii."},{"id":"C","text":"Dacă se folosesc freze, acestea trebuie să fie sferice și utilizate la turație redusă."},{"id":"D","text":"În cavitățile profunde, izolarea dintelui se efectuează după finalizarea completă a exerezei dentinei."},{"id":"E","text":"Instrumentele utilizate pentru exereză trebuie să fie neascuțite pentru a minimiza riscul de perforare a pulpei."}],"correct":["A","C"],"pages":[62],"source":"set-2"},{"id":"set2-dyqG1r0k","fingerprint":"9685f4ded4bdbb26","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Conform principiilor de realizare a formei de contur a unei cavități convenționale, care este adâncimea corectă a peretelui pulpar pentru a asigura o grosime adecvată a materialului de restaurare pe suprafețele ocluzale?","options":[{"id":"A","text":"Peretele pulpar este plasat în dentină la 0,5 mm de joncțiunea amelo-dentinară."},{"id":"B","text":"Peretele pulpar trebuie plasat la o adâncime egală cu grosimea smalțului ocluzal."},{"id":"C","text":"Adâncimea peretelui pulpar este de 1,5-2 mm de la suprafața smalțului, indiferent de poziția joncțiunii amelo-dentinare."},{"id":"D","text":"Peretele pulpar trebuie să fie localizat exact la nivelul joncțiunii amelo-dentinare pentru a conserva dentina."},{"id":"E","text":"Peretele pulpar trebuie plasat la 1,5-2 mm în dentină, măsurat de la joncțiunea amelo-dentinară."}],"correct":["A"],"pages":[62],"source":"set-2"},{"id":"set2-KEe3bz0F","fingerprint":"9806d7a434aa2430","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"În contextul preparării unei cavități de clasa I, cum se procedează în cazul existenței a două leziuni carioase distincte pe aceeași suprafață ocluzală?","options":[{"id":"A","text":"Se realizează o singură cavitate dacă puntea de smalț care le separă are o grosime mai mare de 2 mm."},{"id":"B","text":"Se realizează două cavități distincte dacă țesutul integru care le separă are o grosime de cel puțin 1,5-2 mm."},{"id":"C","text":"Se realizează două cavități distincte doar dacă leziunile se află în fosete diferite, mezială și distală."},{"id":"D","text":"Leziunile se unesc întotdeauna într-o singură cavitate pentru a simplifica procedura."},{"id":"E","text":"Decizia de a uni cavitățile depinde exclusiv de prezența suportului de dentină sănătoasă, indiferent de grosimea punții de smalț."}],"correct":["B"],"pages":[62],"source":"set-2"},{"id":"set2-ry9dM5yb","fingerprint":"01103b650adb0740","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele afirmații descriu corect principiile de realizare a formei de contur pentru o cavitate convențională?","options":[{"id":"A","text":"Forma de contur a cavității se va stabili după îndepărtarea completă a dentinei alterate."},{"id":"B","text":"Smalțul subminat, fără suport de dentină sănătoasă, trebuie conservat pentru a menține structura dentară."},{"id":"C","text":"Marginile cavității trebuie plasate pe vârfurile cuspizilor și pe crestele marginale pentru a asigura retenția."},{"id":"D","text":"Marginile cavității se plasează astfel încât să permită o bună închidere marginală și o bună finisare a restaurării."},{"id":"E","text":"Conturul exterior al cavității trebuie să fie format din curbe line și unghiuri rotunjite."}],"correct":["D","E"],"pages":[62],"source":"set-2"},{"id":"set2-vd4_dHTV","fingerprint":"c0b65be22b68d317","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce reprezintă extensia preventivă în prepararea unei cavități?","options":[{"id":"A","text":"Extinderea preparației pentru a include toate șanțurile și fosetele de pe suprafața ocluzală, indiferent dacă sunt cariate sau nu."},{"id":"B","text":"Plasarea marginilor preparației în plin țesut dentar dur sănătos, pe suprafețe autocurățibile."},{"id":"C","text":"Îndepărtarea profilactică a țesutului sănătos din jurul unei leziuni carioase."},{"id":"D","text":"Lărgirea cavității pentru a permite accesul instrumentarului rotativ de mari dimensiuni."},{"id":"E","text":"Aplicarea unui material de sigilare pe marginile cavității înainte de restaurarea finală."}],"correct":["B"],"pages":[62],"source":"set-2"},{"id":"set2-KnSleywJ","fingerprint":"aee01fd1d5b1771a","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele afirmații referitoare la prepararea unei cavități de clasa I sunt adevărate?","options":[{"id":"A","text":"La marginea preparației se poate lăsa smalț nesusținut de dentină sănătoasă pentru a conserva țesutul dentar."},{"id":"B","text":"Marginile cavității trebuie să includă în totalitate șanțul sau foseta unde este localizat procesul carios."},{"id":"C","text":"Dacă o fosetă de pe peretele preparației este indemnă de carie, ea trebuie inclusă în contur pentru a preveni carierea ulterioară."},{"id":"D","text":"Conturul cavității va fi realizat până la obținerea unei joncțiuni amelo-dentinare indemne de carie."},{"id":"E","text":"Smalțul aparent sănătos trebuie îndepărtat dacă o radiografie indică prezența unei leziuni carioase în dentina subiacentă."}],"correct":["B","D","E"],"pages":[62],"source":"set-2"},{"id":"set2-7dgUFKvb","fingerprint":"deadaadcb900fea7","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt caracteristicile unei preparații ocluzale la un premolar superior cu un proces carios extins în șanțurile din fosetele meziale și distale?","options":[{"id":"A","text":"Preparația trebuie să se extindă obligatoriu pentru a acoperi complet ambii cuspizi."},{"id":"B","text":"Crestele marginale și pantele cuspidiene trebuie păstrate integre, pe cât posibil."},{"id":"C","text":"Istmul vestibulo-oral nu trebuie să depășească 1/3 din distanța dintre vârfurile cuspizilor."},{"id":"D","text":"Preparația are un aspect de \"pișcot\", cu partea cea mai îngustă situată în șanțul intercuspidian."},{"id":"E","text":"Peretele pulpar trebuie să fie realizat întotdeauna concav pentru a crește retenția."}],"correct":["B","C","D"],"pages":[63],"source":"set-2"},{"id":"set2-UoOr5cN1","fingerprint":"5918d1a3e6738d17","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Cum se determină poziția unei cavități ocluzale la premolarii inferiori atunci când șanțul intercuspidian nu este situat central pe fața ocluzală?","options":[{"id":"A","text":"Cavitatea se va plasa mai aproape de cuspidul mai mic pentru a conserva structura celui voluminos."},{"id":"B","text":"Cavitatea se va plasa mai aproape de cuspidul cel mai voluminos."},{"id":"C","text":"Se va evita prepararea cavității în șanțul intercuspidian."},{"id":"D","text":"Cavitatea va avea o formă de \"pișcot\" pentru a compensa asimetria."},{"id":"E","text":"Cavitatea se va centra întotdeauna pe fața ocluzală, indiferent de poziția șanțului."}],"correct":["B"],"pages":[63],"source":"set-2"},{"id":"set2-phy9LwA2","fingerprint":"cb5e568d165c97e4","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt obiectivele extensiei preventive în plan vertical (ocluzo-radicular) pentru o cavitate de clasa a II-a?","options":[{"id":"A","text":"Plasarea peretelui gingival la minimum 2 mm sub aria de contact interdentar."},{"id":"B","text":"Desființarea contactului cu dintele vecin."},{"id":"C","text":"Menținerea unui contact strâns cu dintele vecin pentru a asigura stabilitatea."},{"id":"D","text":"Crearea unor unghiuri interne rotunjite pentru a reduce stresul."},{"id":"E","text":"Îndepărtarea în totalitate a țesuturilor alterate."}],"correct":["A","B","E"],"pages":[63],"source":"set-2"},{"id":"set2-lgd-gAjJ","fingerprint":"2dc1eee333a010c5","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce caracteristici definitorii are preparația unei cavități de clasa a V-a?","options":[{"id":"A","text":"Adâncimea cavității este de 0,5 mm de la joncțiunea amelo-dentinară."},{"id":"B","text":"Peretele gingival se plasează la minim 2 mm sub aria de contact interdentar."},{"id":"C","text":"Forma de contur exterioară este reniformă (bob de fasole)."},{"id":"D","text":"Adâncimea este de 1,5 mm de la joncțiunea amelo-dentinară."},{"id":"E","text":"Extensia preventivă constă în îndepărtarea smalțului demineralizat de la marginile cavității."}],"correct":["A","C","E"],"pages":[63],"source":"set-2"},{"id":"set2-rdcLOIDS","fingerprint":"3de5bf280c3b4bdb","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Prin ce se caracterizează forma de retenție a unei cavități convenționale mici de clasa I?","options":[{"id":"A","text":"Realizarea unui perete pulpar concav pentru a preveni bascularea obturației."},{"id":"B","text":"Rotunjirea sistematică a tuturor unghiurilor interne, indiferent de profunzimea cavității."},{"id":"C","text":"Paralelismul a cel puțin doi pereți verticali în raport cu axul dintelui."},{"id":"D","text":"Prezența unor unghiuri bine definite la joncțiunea dintre pereții verticali și peretele pulpar."},{"id":"E","text":"Realizarea unui perete pulpar plan sau în trepte, care să primească perpendicular forțele ocluzale."}],"correct":["C","D","E"],"pages":[63],"source":"set-2"},{"id":"set2-z1-zU0ct","fingerprint":"16ee2253612fbbb3","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce caracteristică a pereților vestibular și oral ai cavității proximale de clasa a II-a împiedică deplasarea materialului de restaurare spre ocluzal?","options":[{"id":"A","text":"Crearea unor șanțuri de retenție direct pe acești pereți."},{"id":"B","text":"Paralelismul lor strict cu peretele axial."},{"id":"C","text":"Extinderea lor dincolo de aria de contact cu dintele vecin."},{"id":"D","text":"Convergența ușoară a acestora spre ocluzal."},{"id":"E","text":"Divergența acestora spre ocluzal."}],"correct":["D"],"pages":[63],"source":"set-2"},{"id":"set2-1AwFfGrd","fingerprint":"0f15049f05bac9de","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Conform căror specificații se realizează șanțurile de retenție într-o cavitate de clasa a II-a tip slot?","options":[{"id":"A","text":"Trebuie să lase o grosime de 0,25-0,50 mm de dentină între șanțuri și joncțiunea amelo-dentinară (JAD)."},{"id":"B","text":"Se realizează obligatoriu la joncțiunea amelo-dentinară pentru retenție maximă."},{"id":"C","text":"Trebuie să fie distincte, cu o adâncime și lățime de cel puțin 0,5 mm."},{"id":"D","text":"Se plasează în dentină, în unghiul de întâlnire al peretelui vestibular și oral cu cel axial."},{"id":"E","text":"Se utilizează o freză sferică de 0,5 mm."}],"correct":["A","C","D","E"],"pages":[63],"source":"set-2"},{"id":"set2-QLs1QsHD","fingerprint":"a9a3e581ce0aeaf8","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt caracteristicile peretelui gingival al unei cavități verticale, conform principiului asigurării retenției al lui Black?","options":[{"id":"A","text":"Este situat la 1,5-2 mm sub aria de contact interdentară."},{"id":"B","text":"Este întotdeauna înclinat divergent față de peretele axial pentru a crea retenție."},{"id":"C","text":"Un șanț de retenție poate fi preparat la joncțiunea sa cu peretele axial."},{"id":"D","text":"Trebuie să fie localizat exclusiv în dentină sănătoasă."},{"id":"E","text":"Orientarea sa previne existența smalțului nesusținut de dentină la marginea gingivală."}],"correct":["A","C","E"],"pages":[64],"source":"set-2"},{"id":"set2-WYjvcqOK","fingerprint":"950239ae0a81d322","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce elemente structurale ale unei preparații cavitare se opun tendinței de dislocare sagitală (mezio-distală) a obturației?","options":[{"id":"A","text":"Întâlnirea în unghiuri bine definite a pereților oral și vestibular cu peretele parapulpar."},{"id":"B","text":"Bizotarea unghiului de întâlnire dintre peretele pulpar și cel parapulpar."},{"id":"C","text":"Unghiul drept sau ascuțit format la joncțiunea dintre peretele gingival și cel parapulpar."},{"id":"D","text":"Crearea a patru puțuri de retenție în punctele axiale ale preparației."},{"id":"E","text":"Retenția asigurată de cavitatea orizontală preparată în formă de coadă de rândunică."}],"correct":["A","C","E"],"pages":[64],"source":"set-2"},{"id":"set2-5Ff48YWO","fingerprint":"2fcd5305274bc02a","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care afirmație descrie corect un raport dimensional sau structural între cavitatea orizontală și cea verticală a unei preparații?","options":[{"id":"A","text":"Unghiul de întâlnire dintre peretele pulpar și cel parapulpar se lasă ascuțit pentru a crește retenția."},{"id":"B","text":"Adâncimea cavității orizontale trebuie să fie aproximativ 1/3 din înălțimea totală a cavității verticale."},{"id":"C","text":"La dinții abrazați, adâncimea cavității orizontale se reduce pentru a conserva țesutul dentar."},{"id":"D","text":"Istmul de întâlnire dintre cele două cavități trebuie să fie 1/2 din lățimea dintelui."},{"id":"E","text":"Axurile celor două cavități trebuie să se afle în plane perpendiculare pentru a maximiza retenția."}],"correct":["B"],"pages":[64],"source":"set-2"},{"id":"set2-RyHelMHG","fingerprint":"c75c96e6f232b97a","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Prin ce metode se poate realiza retenția în cazul unei cavități de clasa a III-a?","options":[{"id":"A","text":"Prin realizarea a două șanțuri în unghiurile de întâlnire ale pereților incizal și gingival cu peretele parapulpar."},{"id":"B","text":"Prin utilizarea de știfturi parapulpare cimentate sau înșurubate în dentină."},{"id":"C","text":"Prin prepararea unei cavități de retenție în formă de coadă de rândunică pe fața orală, în cazul leziunilor mari."},{"id":"D","text":"Prin conservarea unei porțiuni cât mai mari din peretele prin care s-a realizat accesul."},{"id":"E","text":"Prin întâlnirea pereților laterali cu peretele parapulpar în unghiuri ascuțite."}],"correct":["C","D","E"],"pages":[64],"source":"set-2"},{"id":"set2-t6ayX488","fingerprint":"50adfddafbc24ecd","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"În cazul unei distrucții a unghiului incizal prin traumatism (cavitate de clasa a IV-a), care este secvența corectă de manopere terapeutice?","options":[{"id":"A","text":"Se bizotează marginile de smalț și se realizează restaurarea coronară cu materiale aderente."},{"id":"B","text":"Se îndepărtează dentina alterată, se realizează unghiuri bine exprimate și se plasează știfturi parapulpare."},{"id":"C","text":"Se realizează o cavitate cu pereți laterali divergenți spre peretele parapulpar și se restaurează."},{"id":"D","text":"Se prepară o cavitate suplimentară de retenție pe fața orală și se restaurează cu materiale neaderente."},{"id":"E","text":"Se prepară patru puțuri de retenție în punctele axiale și se bizotează marginile."}],"correct":["A"],"pages":[64],"source":"set-2"},{"id":"set2-N2dMsLh1","fingerprint":"440b377885ef6778","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care este principiul de bază pentru obținerea retenției într-o cavitate de clasa a V-a?","options":[{"id":"A","text":"Realizarea a patru puțuri de retenție în cele patru puncte axiale ale preparației."},{"id":"B","text":"Înclinarea divergentă a pereților laterali spre peretele parapulpar al cavității."},{"id":"C","text":"Accentuarea unghiului incizal și a celui gingival."},{"id":"D","text":"Convexitatea accentuată a peretelui parapulpar care urmărește conturul extern al dintelui."},{"id":"E","text":"Crearea unui șanț de retenție în unghiul de întâlnire dintre pereții laterali și cel parapulpar."}],"correct":["B"],"pages":[64],"source":"set-2"},{"id":"set2-MJKbYwHr","fingerprint":"248bbb353cff3e63","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele sunt considerate metode suplimentare de retenție pentru o cavitate de clasa a V-a?","options":[{"id":"A","text":"Realizarea a două șanțuri la joncțiunea peretelui incizal, respectiv gingival, cu peretele parapulpar."},{"id":"B","text":"Prepararea unei cavități în formă de coadă de rândunică pe fața orală."},{"id":"C","text":"Un șanț de retenție realizat în unghiul de întâlnire dintre pereții laterali și peretele parapulpar."},{"id":"D","text":"Crearea a patru puțuri de retenție în cele patru puncte axiale ale preparației."},{"id":"E","text":"Utilizarea de știfturi parapulpare cimentate sau înșurubate."}],"correct":["A","C","D"],"pages":[64],"source":"set-2"},{"id":"set2-GrQXPuqM","fingerprint":"c452bd4987c56455","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt principiile generale ce trebuie respectate pentru a asigura forma de rezistență a unei preparații dentare?","options":[{"id":"A","text":"Orientarea pereților cavității trebuie să fie perpendiculară sau paralelă cu direcția de transmitere a forțelor masticatorii."},{"id":"B","text":"Se pot păstra porțiuni de smalț subțiate, cu condiția să nu fie localizate în zone de contact ocluzal direct."},{"id":"C","text":"Extensia marginilor cavității trebuie să conserve cuspizii și crestele marginale, chiar dacă aceștia nu sunt susținuți de dentină sănătoasă."},{"id":"D","text":"Trebuie asigurată o grosime de cel puțin 2 mm pentru materialul de restaurare."},{"id":"E","text":"Nu se păstrează porțiuni de smalț fără inserție pe dentină subiacentă sănătoasă."}],"correct":["A","E"],"pages":[65],"source":"set-2"},{"id":"set2-9MkO0U86","fingerprint":"2472e6ea9aeaf0a6","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"În cazul unei cavități de clasa I, ce unghi trebuie să formeze pereții de smalț cu suprafața externă a dintelui pentru a asigura o rezistență adecvată?","options":[{"id":"A","text":"80-90°."},{"id":"B","text":"Mai mare de 110°, pentru a proteja cuspizii adiacenți."},{"id":"C","text":"Prismele de smalț dictează un unghi paralel cu axul lung al dintelui."},{"id":"D","text":"90°-110°."},{"id":"E","text":"Mai mic de 90°, pentru a favoriza retenția mecanică a materialului."}],"correct":["D"],"pages":[65],"source":"set-2"},{"id":"set2-yBRULn7G","fingerprint":"b14d304c73c802cd","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt specificațiile corecte privind dimensiunile preparației pentru o cavitate de clasa I, în vederea asigurării rezistenței?","options":[{"id":"A","text":"Peretele pulpar se prepară la 0,5-1 mm de joncțiunea amelo-dentinară."},{"id":"B","text":"Lățimea vestibulo-orală trebuie să fie de 1/3 din distanța dintre vârful cuspidului vestibular și cel oral."},{"id":"C","text":"Lățimea vestibulo-orală trebuie să fie de cel puțin 1/4 din distanța intercuspidiană."},{"id":"D","text":"Peretele pulpar trebuie preparat la 1,5-2 mm de joncțiunea amelo-dentinară, în dentină sănătoasă."},{"id":"E","text":"Materialul de restaurare trebuie să aibă o grosime minimă de 2,5 mm."}],"correct":["A","B"],"pages":[65],"source":"set-2"},{"id":"set2-1aqGNkgU","fingerprint":"1d32493a4d981538","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce măsuri se iau pentru asigurarea formei de rezistență în cazul unei preparații de clasa a II-a?","options":[{"id":"A","text":"Pereții vestibular sau oral ai cavității verticale, constituiți numai din smalț, se scurtează din înălțime."},{"id":"B","text":"În cazul cuspizilor nesusținuți de dentină sănătoasă, se recomandă căptușirea bolților cuspidiene."},{"id":"C","text":"Pereții vestibulari și orali ai cavității ocluzale de retenție trebuie să fie convergenți spre ocluzal."},{"id":"D","text":"Cavitatea orizontală (ocluzală) este preparată la o adâncime de 2 mm în dentină pentru a asigura rezistența."},{"id":"E","text":"Istmul, zona de întâlnire între cele două cavități, trebuie să fie ascuțit pentru a crește retenția."}],"correct":["A","B"],"pages":[65],"source":"set-2"},{"id":"set2-6kqLd1ZB","fingerprint":"cd633fb974865d5b","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Referitor la forma de rezistență în cavitățile de clasa a III-a, care dintre următoarele afirmații este corectă?","options":[{"id":"A","text":"Se pot face concesii în ceea ce privește rezistența, din motive fizionomice."},{"id":"B","text":"Nu pun probleme deosebite în ceea ce privește rezistența, similar claselor IV și V."},{"id":"C","text":"Pereții de smalț trebuie să formeze unghiuri de 80° cu suprafața dintelui pentru a crește rezistența."},{"id":"D","text":"Grosimea minimă a materialului de restaurare trebuie să fie de 2 mm."},{"id":"E","text":"Unghiul incizal subminat trebuie întotdeauna îndepărtat pentru a preveni fractura."}],"correct":["A"],"pages":[65],"source":"set-2"},{"id":"set2-fJmisVt0","fingerprint":"6d4a8a483a6fbc5f","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce etapă a preparării cavității are ca scop asigurarea unei configurații liniare, netede, fără anfractuozități a pereților și include bizotarea marginală?","options":[{"id":"A","text":"Asigurarea retenției"},{"id":"B","text":"Finisarea marginilor cavității"},{"id":"C","text":"Asigurarea rezistenței"},{"id":"D","text":"Căptușirea bolților cuspidiene"},{"id":"E","text":"Realizarea istmului rotunjit"}],"correct":["B"],"pages":[65],"source":"set-2"},{"id":"set2-aF0TqWXU","fingerprint":"5ab136cf83180c07","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt principiile generale de care trebuie să se țină seama la finisarea marginilor de smalț ale unei preparații dentare?","options":[{"id":"A","text":"Este obligatorie crearea unui unghi ascuțit, sub 90 de grade, pentru a crește retenția."},{"id":"B","text":"Materialul utilizat pentru restaurare influențează tehnica de finisare."},{"id":"C","text":"Localizarea marginilor preparației este un factor important."},{"id":"D","text":"Direcția prismelor de smalț trebuie luată în considerare."},{"id":"E","text":"Prismele de smalț secționate la nivelul marginilor externe trebuie să fie sprijinite pe prismele subiacente."}],"correct":["B","C","D","E"],"pages":[66],"source":"set-2"},{"id":"set2-0F1vNVHk","fingerprint":"6b2a01a04946bae9","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care este unghiul ideal pe care trebuie să îl formeze marginile de smalț ale unei cavități convenționale de clasa I cu suprafața externă a dintelui?","options":[{"id":"A","text":"115-125º"},{"id":"B","text":"90-110º"},{"id":"C","text":"Unghiul nu este important, ci doar netezimea marginilor."},{"id":"D","text":"70-85º"},{"id":"E","text":"Exact 130º"}],"correct":["B"],"pages":[66],"source":"set-2"},{"id":"set2-5WrA80EG","fingerprint":"27da38a0e3ff7bce","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce manopere specifice de finisare se aplică la nivelul cavității verticale într-o preparație de clasa a II-a?","options":[{"id":"A","text":"Bizotarea tuturor marginilor cavității verticale."},{"id":"B","text":"Bizotarea pragului gingival."},{"id":"C","text":"Netezirea marginilor pereților vestibular și oral."},{"id":"D","text":"Crearea unor pereți cu configurație lineară, similar cu cavitatea orizontală."},{"id":"E","text":"Menținerea unui unghi de 90-110º la nivelul pragului gingival."}],"correct":["B","C"],"pages":[66],"source":"set-2"},{"id":"set2-S4d5obJB","fingerprint":"5dd72bc5d080003e","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"În ce context se recomandă bizotarea marginilor de smalț pentru cavitățile de clasa a III-a, a IV-a și a V-a?","options":[{"id":"A","text":"În toate cazurile, indiferent de materialul de restaurare."},{"id":"B","text":"Doar în situația unor cavități de mare întindere."},{"id":"C","text":"Atunci când preparația este realizată exclusiv cu instrumentar de mână."},{"id":"D","text":"Când se urmărește exclusiv obținerea unor margini netede, cu linii curbe."},{"id":"E","text":"Când se utilizează materiale de restaurare aderente."}],"correct":["E"],"pages":[66],"source":"set-2"},{"id":"set2-Vh4SmnMD","fingerprint":"6e1a86d7c600ee90","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt etapele descrise pentru toaleta finală a unei cavități preparate, înainte de tratamentul plăgii dentinare?","options":[{"id":"A","text":"Verificarea finală a retenției cu o sondă rigidă."},{"id":"B","text":"Izolarea dintelui și uscarea cavității cu jet de aer."},{"id":"C","text":"Spălarea cavității cu jet de apă."},{"id":"D","text":"Aplicarea unui agent demineralizant pe pereții cavității."},{"id":"E","text":"Tratamentul plăgii dentinare imediat după spălarea cu apă."}],"correct":["B","C"],"pages":[66],"source":"set-2"},{"id":"set2-Q52AfEiL","fingerprint":"d98ee4d3fc2496b7","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt afirmațiile adevărate privind atitudinea terapeutică față de stadiile evolutive ale leziunilor carioase simple?","options":[{"id":"A","text":"Leziunile cavitare necesită o abordare terapeutică operatorie convențională, caracterizată prin invazivitate."},{"id":"B","text":"Leziunile carioase incipiente necavitare necesită o abordare terapeutică neconvențională de tip neinvaziv, micro sau minim invaziv."},{"id":"C","text":"Leziunile cavitare sunt abordate exclusiv prin tehnici neinvazive pentru a respecta principiul economiei țesuturilor dure dentare."},{"id":"D","text":"Tratamentul leziunilor carioase este dependent de gradul de evoluție și de extinderea procesului carios."},{"id":"E","text":"Profilaxia presupune tratamentul curativ al leziunilor carioase cavitare în stadii incipiente."}],"correct":["A","B","D"],"pages":[59,60],"source":"set-2"},{"id":"set2-c5qpz4-P","fingerprint":"ae5db311bbe3c659","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care este scopul principal al fazei de tratament medicamentos în cadrul terapiei convenționale a cariei simple?","options":[{"id":"A","text":"Tratamentul plăgii dentinare expuse și realizarea protecției dentino-pulpare."},{"id":"B","text":"Crearea unei preparații care să permită inserarea și menținerea restaurării în interiorul său."},{"id":"C","text":"Plasarea limitelor preparației pentru prevenirea apariției cariei secundare marginale."},{"id":"D","text":"Refacerea morfofuncțională a dintelui prin tehnici directe, semidirecte sau indirecte."},{"id":"E","text":"Îndepărtarea țesuturilor dure dentare alterate ireversibil de procesul carios."}],"correct":["A"],"pages":[59,60],"source":"set-2"},{"id":"set2-ybmgDZej","fingerprint":"568f37c1ab6a9278","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt obiectivele preparării cavităților în tratamentul cariei simple?","options":[{"id":"A","text":"Plasarea limitelor preparației cât mai conservator posibil pentru a preveni instalarea cariei secundare marginale."},{"id":"B","text":"Conformarea și dimensionarea preparației pentru a evita fractura ansamblului dinte/restaurare coronară sub acțiunea forțelor."},{"id":"C","text":"Îndepărtarea în totalitate a țesuturilor dure dentare restante pentru a preveni dizlocarea restaurării."},{"id":"D","text":"Realizarea exclusivă a retenției mecanice prin tehnici semidirecte."},{"id":"E","text":"Îndepărtarea substanței dure dentare alterate ireversibil, incluzând smalțul, dentina și cementul."}],"correct":["A","B","E"],"pages":[59,60],"source":"set-2"},{"id":"set2-HfjTBZk2","fingerprint":"55485cc0f9ecc239","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următorii factori condiționează efectuarea preparației cavităților în tratamentul leziunilor carioase?","options":[{"id":"A","text":"Statusul general al pacientului, determinat de factori exclusiv de natură financiară."},{"id":"B","text":"Structurile odontale implicate, incluzând organul pulpar și parodonțiul marginal superficial."},{"id":"C","text":"Structurile dento-maxilare corelate, cum ar fi dinții adiacenți, antagoniști și relația ocluzală intermaxilară."},{"id":"D","text":"Statusul general al pacientului, incluzând vârsta, starea de sănătate sistemică și motivația privind tratamentul."},{"id":"E","text":"Tipul de restaurare morfofuncțională, determinat de materialele și tehnicile utilizate."}],"correct":["B","C","D","E"],"pages":[59,60],"source":"set-2"},{"id":"set2-MRs94CCt","fingerprint":"c54da33df39f66ae","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Ce presupune respectarea principiilor biointegrării în cadrul fazei de tratament chirurgical al cariei simple?","options":[{"id":"A","text":"Tratamentul profilactic al plăgii dentinare fără îndepărtarea prealabilă a smalțului alterat."},{"id":"B","text":"Refacerea morfofuncțională a dintelui afectat aplicând exclusiv metode indirect-directe."},{"id":"C","text":"Asigurarea biocompatibilității, a funcționalității, a esteticii și prevenirea recidivelor."},{"id":"D","text":"Utilizarea exclusivă a tehnicilor de cariodetecție neconvenționale pentru diagnostic."},{"id":"E","text":"Sistarea evoluției procesului carios exclusiv prin metode neinvazive la nivelul parodonțiului marginal."}],"correct":["C"],"pages":[59,60],"source":"set-2"},{"id":"set2-fxaVtK5U","fingerprint":"c0c4135160ea9ada","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt localizările caracteristice cavităților de clasa I în funcție de dispunerea procesului carios?","options":[{"id":"A","text":"Fosetele supracingulare de pe fețele palatinale ale frontalilor superiori."},{"id":"B","text":"Fețele proximale ale molarilor și premolarilor."},{"id":"C","text":"Șanțurile și fosetele vestibulare și orale ale premolarilor."},{"id":"D","text":"Vârfurile cuspizilor la nivelul molarilor și premolarilor."},{"id":"E","text":"Șanțurile și fosetele ocluzale ale molarilor și premolarilor."}],"correct":["A","E"],"pages":[60],"source":"set-2"},{"id":"set2-oH6HBECF","fingerprint":"3e47b02e293b0b99","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce categorii de leziuni se încadrează în localizarea descrisă drept Site 2?","options":[{"id":"A","text":"Leziunile localizate pe fețele proximale la dinții frontali."},{"id":"B","text":"Leziunile localizate pe fețele proximale la dinții laterali."},{"id":"C","text":"Leziunile situate pe marginea incizală a dinților frontali."},{"id":"D","text":"Leziunile localizate în zona cervicală a dinților frontali și laterali."},{"id":"E","text":"Leziunile localizate pe suprafața radiculară."}],"correct":["A","B"],"pages":[60],"source":"set-2"},{"id":"set2-ZglgJmPk","fingerprint":"68e971a4ef1aff65","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt afirmațiile adevărate privind clasificarea leziunilor carioase în funcție de dimensiunea acestora?","options":[{"id":"A","text":"Stadiul mare (Size 4) se referă la o leziune cavitară ce afectează strict dentina din treimea medie."},{"id":"B","text":"Stadiul minim (Size 2) descrie o leziune cavitară de dimensiuni reduse, cu afectarea stratului extern al dentinei."},{"id":"C","text":"Stadiul extins presupune o leziune cavitară cu afectarea stratului extern al smalțului, fără interesare dentinară."},{"id":"D","text":"Stadiul incipient (Size 0) este o leziune necavitară ce beneficiază de un tratament neinvaziv."},{"id":"E","text":"Stadiul mediu (Size 3) implică afectarea profundă a dentinei."}],"correct":["B","D"],"pages":[60],"source":"set-2"},{"id":"set2-FmRdV2W5","fingerprint":"6ebb3ccc63489c72","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce caracteristici prezintă cavitățile rezultate în urma tratamentului proceselor carioase în funcție de dispunerea lor topografică?","options":[{"id":"A","text":"Cavitatea de clasa a II-a este limitată obligatoriu la o singură față proximală a molarilor sau premolarilor."},{"id":"B","text":"Cavitatea de clasa a VI-a interesează muchia incizală a dinților frontali sau vârfurile cuspizilor la molari și premolari."},{"id":"C","text":"Cavitatea de clasa a V-a este situată pe fețele vestibulare și orale ale tuturor dinților, în treimea medie."},{"id":"D","text":"Cavitatea de clasa a IV-a implică fețele proximale ale dinților frontali și afectează unghiul incizal."},{"id":"E","text":"Cavitatea de clasa a III-a se localizează pe fețele proximale ale dinților frontali, păstrând unghiul incizal."}],"correct":["B","D","E"],"pages":[60],"source":"set-2"},{"id":"set2-kq9LUTN9","fingerprint":"e337778a682330a7","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Ce asocieri sunt corecte între localizarea leziunilor clasificate pe situri și sistemul clasic bazat pe clasele de cavități?","options":[{"id":"A","text":"Leziunile situate pe muchia incizală a dinților frontali sunt încadrate în categoria Site 3."},{"id":"B","text":"Categoria Site 2 include leziunile ce corespund cavităților de clasa a II-a, a III-a și a IV-a."},{"id":"C","text":"Categoria Site 1 include exclusiv leziunile ce corespund cavităților de clasa I."},{"id":"D","text":"Categoria Site 3 include leziunile ce corespund cavităților de clasa a V-a."},{"id":"E","text":"Leziunile corespunzătoare cavităților de clasa a VI-a sunt incluse în categoria Site 1."}],"correct":["B","D","E"],"pages":[60],"source":"set-2"},{"id":"set2-a3rEq35n","fingerprint":"84ab36aaee3daa7d","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt posibilitățile de realizare a accesului în cazul leziunilor carioase de clasa a III-a?","options":[{"id":"A","text":"Separarea temporară a dinților utilizează separatorul Ivory pentru facilitarea unui acces indirect la procesul carios."},{"id":"B","text":"Abordarea dinspre suprafața orală asigură un acces direct atunci când creasta marginală este doar subminată."},{"id":"C","text":"În cazul cariilor localizate pe mijlocul feței proximale, abordarea indirectă este recomandat a fi realizată dinspre suprafața orală."},{"id":"D","text":"Leziunile carioase care au evoluat spre suprafața vestibulară beneficiază de un acces direct."},{"id":"E","text":"Prezența malpozițiilor dentare, a tremelor sau absența dintelui vecin permite un acces direct la nivelul feței proximale."}],"correct":["C","D","E"],"pages":[61],"source":"set-2"},{"id":"set2-CyjYWLiA","fingerprint":"eb4055a81de64464","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care dintre următoarele afirmații descrie conduita optimă în etapa de exereză a dentinei alterate?","options":[{"id":"A","text":"Instrumentele manuale trebuie să aibă marginile de tăiere tocite, pentru a reduce riscul de perforare accidentală a camerei pulpare."},{"id":"B","text":"Utilizarea instrumentarului rotativ impune folosirea frezelor cilindrice la turație redusă, adaptate la dimensiunea procesului carios."},{"id":"C","text":"În cavitățile profunde, izolarea dintelui se realizează anterior exerezei dentinei alterate de pe pereții pulpar și parapulpar."},{"id":"D","text":"Îndepărtarea țesuturilor necrozate se inițiază la nivelul peretelui pulpar, finalizându-se pe pereții laterali ai cavității."},{"id":"E","text":"Turația înaltă a instrumentarului rotativ este de primă intenție deoarece minimizează generarea de căldură transmisă pulpei."}],"correct":["C"],"pages":[62],"source":"set-2"},{"id":"set2-W_L0lxsz","fingerprint":"a8e1e20b55a4fbb9","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt condițiile clinice ce trebuie îndeplinite pentru a se accepta păstrarea unor zone punctiforme de dentină alterată în dreptul coarnelor pulpare, la nivelul unei cavități profunde?","options":[{"id":"A","text":"Dintele respectiv să nu prezinte în antecedente simptomatologie caracteristică inflamației pulpare."},{"id":"B","text":"Prezența la nivelul dintelui afectat a unui istoric recent și tranzitoriu de simptomatologie specifică inflamației pulpare."},{"id":"C","text":"Pacientul să se afle la o vârstă tânără și să fie clinic sănătos."},{"id":"D","text":"Existența unui acces direct în cavitate, care să permită efectuarea cu ușurință a manoperelor terapeutice."},{"id":"E","text":"Realizarea tratamentului plăgii dentinare printr-o tehnică de coafaj direct într-un singur timp operator."}],"correct":["A","C","D"],"pages":[61],"source":"set-2"},{"id":"set2-9YDuEsgb","fingerprint":"aae149137d0d0d1e","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt regulile care ghidează gradul de exereză a dentinei alterate în raport cu profunzimea leziunii carioase?","options":[{"id":"A","text":"În leziunile superficiale, îndepărtarea țesutului alterat se oprește la nivelul dentinei cu consistență scăzută, de colorație normală."},{"id":"B","text":"În cavitățile superficiale, țesutul dentar alterat se excizează integral până în smalț și dentină dură sănătoasă, având o colorație normală."},{"id":"C","text":"La nivelul cavităților de adâncime medie, se excizează țesutul afectat până în dentină dură sănătoasă sau dentină dură pigmentată."},{"id":"D","text":"Menținerea dentinei dure pigmentate pe podeaua cavităților profunde reprezintă o abatere majoră de la principiile exerezei."},{"id":"E","text":"Principiul îndepărtării totale a dentinei alterate admite concesii pentru prevenirea expunerii pulpare, condiționat de factori locali și generali."}],"correct":["B","C","E"],"pages":[61],"source":"set-2"},{"id":"set2-ABxWiNBe","fingerprint":"32de8fb57521cfdc","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele afirmații descriu în mod corect procedurile specifice și scopul etapei de deschidere a procesului carios?","options":[{"id":"A","text":"Deschiderea are ca obiectiv singular vizualizarea limitelor de suprafață și profunzime, fără influență asupra manoperelor de preparare."},{"id":"B","text":"În cazul cavităților de clasa a II-a localizate sub aria de contact interdentar, dar cu creasta marginală integră, etapa de ușurare a accesului devine o necesitate."},{"id":"C","text":"Etapa de ușurare a accesului se omite sistematic în leziunile carioase de clasa I, indiferent de dimensiunea leziunii de suprafață."},{"id":"D","text":"Principiile mecanice fundamentale impun deschiderea unui proces carios într-un singur timp, fiind exclusă abordarea stadializată a accesului."},{"id":"E","text":"Accesul direct la o leziune de clasa a II-a este asigurat în mod intrinsec în situația în care procesul carios a întrerupt continuitatea crestei marginale."}],"correct":["B","E"],"pages":[61],"source":"set-2"},{"id":"set2-VePu7jsH","fingerprint":"1b813bbb7adc793c","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt principiile de bază aplicate în realizarea formei de contur pentru o cavitate convențională?","options":[{"id":"A","text":"Marginile cavității se plasează în zonele cariosusceptibile pentru a preveni extensia secundară a cariei."},{"id":"B","text":"Conturul exterior trebuie realizat din curbe line, unghiuri rotunjite și linii drepte."},{"id":"C","text":"La nivelul suprafețelor ocluzale, se creează un spațiu de 1,5-2 mm grosime pentru materialul de restaurare."},{"id":"D","text":"Peretele pulpar este plasat în dentină la 0,5 mm de joncțiunea amelo-dentinară."},{"id":"E","text":"Marginile cavității se situează pe vârfurile cuspizilor și pe crestele marginale pentru a asigura curățirea artificială."}],"correct":["B","C","D"],"pages":[62],"source":"set-2"},{"id":"set2-9152o_xz","fingerprint":"6addaba036cea342","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt afirmațiile valabile privind extensia preventivă și forma de contur pentru o cavitate de clasa I?","options":[{"id":"A","text":"O fosetă indemnă de carie aflată la nivelul pereților preparației se include obligatoriu prin lărgirea cavității."},{"id":"B","text":"Smalțul aparent sănătos sub care radiografia indică o leziune dentinară se conservă pentru protecția pulpei dentare."},{"id":"C","text":"Marginile cavității se plasează astfel încât șanțul sau foseta afectată de procesul carios să fie inclusă în totalitate în contur."},{"id":"D","text":"Două leziuni carioase ocluzale distincte necesită realizarea unor cavități separate doar dacă țesutul integru dintre ele are o grosime de cel puțin 1,5-2 mm."},{"id":"E","text":"Preparația exclude prezența smalțului lipsit de suportul dentinei sănătoase la marginile ei."}],"correct":["C","D","E"],"pages":[62],"source":"set-2"},{"id":"set2-xFseFA4f","fingerprint":"805ea936037eabcf","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care este regula dimensională și de design aplicată la prepararea unui premolar superior cu un proces carios ocluzal situat în șanțul intercuspidian și extins în șanțurile din fosetele meziale și distale?","options":[{"id":"A","text":"Marginile preparației se extind sistematic pentru a desființa pantele cuspidiene și crestele marginale."},{"id":"B","text":"Peretele gingival al preparației se plasează la minim 2 mm sub aria de contact interdentar."},{"id":"C","text":"Preparația va lua un aspect de „pișcot” sau de „fluture”, având partea cea mai îngustă în sens vestibulo-oral situată în șanțul intercuspidian."},{"id":"D","text":"Preparația primește o formă exterioară reniformă cu o adâncime de 0,5 mm de la joncțiunea amelo-dentinară."},{"id":"E","text":"Cavitatea ocluzală se va poziționa mai aproape de cuspidul cel mai voluminos."}],"correct":["C"],"pages":[62],"source":"set-2"},{"id":"set2-rRGytx6z","fingerprint":"500c1cb833ce3384","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt particularitățile dimensionale și topografice ale cavităților de clasa a II-a și a V-a pe parcursul realizării extensiei preventive?","options":[{"id":"A","text":"Adâncimea preparării în cazul cavității de clasa a V-a este de 0,5 mm de la joncțiunea amelo-dentinară."},{"id":"B","text":"Cavitatea de clasa a V-a are o formă exterioară reniformă și o adâncime constantă de 1,5-2 mm."},{"id":"C","text":"Extensia preventivă la cavitatea orizontală de clasa a II-a se realizează identic cu cea a unei cavități de clasa I."},{"id":"D","text":"La cavitatea verticală de clasa a II-a, peretele gingival se plasează la un minim de 2 mm sub aria de contact interdentar."},{"id":"E","text":"Extensia cavității verticale de clasa a II-a se efectuează exclusiv în plan vertical, adică ocluzo-radicular."}],"correct":["A","C","D"],"pages":[63],"source":"set-2"},{"id":"set2-NyS0YuOt","fingerprint":"2f5dc16a41adb7f3","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care este principiul fundamental care definește realizarea extensiei preventive în tratamentul cariei simple?","options":[{"id":"A","text":"Poziționarea peretelui pulpar la minim 2 mm sub joncțiunea amelo-dentinară pe suprafețele ocluzale."},{"id":"B","text":"Păstrarea contactului interdentar intact în cursul preparării cavității verticale de clasa a II-a."},{"id":"C","text":"Îndepărtarea exclusivă a dentinei alterate, cu conservarea integrală a smalțului demineralizat de la marginile cavităților de clasa a V-a."},{"id":"D","text":"Plasarea marginilor preparației în plin țesut dentar dur sănătos, pe suprafețe autocurățibile sau accesibile curățirii artificiale."},{"id":"E","text":"Lărgirea cavităților de clasa a III-a și a IV-a impune un sacrificiu considerabil de țesut dentar din rațiuni pur mecanice."}],"correct":["D"],"pages":[62],"source":"set-2"},{"id":"set2-VnD1uXRI","fingerprint":"bde3fe0abb380802","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt afirmațiile adevărate referitoare la forma de retenție a cavității de clasa I?","options":[{"id":"A","text":"Este suficient paralelismul a cel puțin 2 pereți verticali în raport cu axul dintelui, pentru o cavitate convențională mică."},{"id":"B","text":"Unghiurile interne trebuie să fie mai rotunjite în cazul cavităților profunde."},{"id":"C","text":"Peretele pulpar poate fi preparat în formă concavă pentru a spori stabilitatea obturației și a preveni bascularea."},{"id":"D","text":"Peretele pulpar trebuie să primească forțele ocluzale perpendicular pe suprafața sa."},{"id":"E","text":"În cavitățile extinse, peretele pulpar asimetric elimină necesitatea utilizării mijloacelor suplimentare de retenție."}],"correct":["A","B","D"],"pages":[63],"source":"set-2"},{"id":"set2-jzqDqEvT","fingerprint":"8c494324147bfce0","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele caracteristici descriu corect cerințele preparării cavității proximale și a cavității tip slot la clasa a II-a?","options":[{"id":"A","text":"Pereții vestibular și oral trebuie să fie divergenți spre ocluzal pentru a favoriza retenția materialului."},{"id":"B","text":"Între șanțurile de retenție și joncțiunea amelo-dentinară trebuie să rămână un strat de dentină de 0,25-0,50 mm."},{"id":"C","text":"Preparația trebuie să aibă o dimensiune mezio-distală de minimum 1,5 mm."},{"id":"D","text":"Șanțurile de retenție realizate cu o freză sferică de 0,5 mm trebuie să aibă cel puțin 0,5 mm în adâncime și 0,5 mm în lățime."},{"id":"E","text":"Șanțurile de retenție se realizează exact pe linia joncțiunii amelo-dentinare pentru a asigura rezistența maximă a peretelui."}],"correct":["B","C","D"],"pages":[63],"source":"set-2"},{"id":"set2-lrztBh2C","fingerprint":"111d8e61844f2ea6","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Cum se stabilesc rapoartele dintre cavitatea orizontală și cea verticală într-o preparație de clasa a II-a, atunci când sunt desfășurate într-un plan?","options":[{"id":"A","text":"Lățimea istmului de întâlnire dintre cele două cavități trebuie să fie aproximativ jumătate din lățimea dintelui măsurată la nivelul vârfului cuspizilor."},{"id":"B","text":"Unghiul de întâlnire dintre peretele pulpar și parapulpar se va teși (bizota) pentru a preveni fracturarea materialului de restaurare."},{"id":"C","text":"Axul celor două cavități trebuie să fie situat în același plan."},{"id":"D","text":"La dinții abrazați, adâncimea cavității orizontale va respecta strict raportul de o treime din înălțimea verticală."},{"id":"E","text":"Adâncimea cavității orizontale trebuie să fie aproximativ o treime din înălțimea totală a cavității verticale."}],"correct":["B","C","E"],"pages":[64],"source":"set-2"},{"id":"set2-fBDxE7Ly","fingerprint":"00174db81b6e6bcc","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Identificați afirmațiile corecte referitoare la principiile de obținere a retenției în cavitățile de clasa a III-a și clasa a V-a:","options":[{"id":"A","text":"Pereții laterali ai cavității de clasa a V-a sunt perpendiculari pe suprafața externă a smalțului."},{"id":"B","text":"Pentru suplimentarea retenției la clasa a V-a, se pot realiza 4 puțuri de retenție în cele 4 puncte axiale ale preparației."},{"id":"C","text":"La cavitatea de clasa a III-a, unghiurile de întâlnire dintre pereții laterali și peretele parapulpar trebuie să fie ascuțite."},{"id":"D","text":"La cavitatea de clasa a V-a, peretele parapulpar se prepară sub formă concavă în sens mezio-distal pentru a spori volumul retenției."},{"id":"E","text":"La cavitatea de clasa a III-a, se recomandă suprimarea sau rotunjirea unghiului incizal pentru a distribui forțele ocluzale."}],"correct":["A","B","C"],"pages":[64],"source":"set-2"},{"id":"set2-qvjYmKGr","fingerprint":"9cbc764b24d63fea","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care dintre următoarele elemente morfologice ale preparației de clasa a II-a au rolul direct de a se opune tendinței de dislocare sagitală (mezio-distală) a obturației?","options":[{"id":"A","text":"Întâlnirea pereților oral și vestibular cu peretele parapulpar în unghiuri bine exprimate."},{"id":"B","text":"Convergența pereților vestibular și oral spre ocluzal."},{"id":"C","text":"Crearea unui unghi obtuz între peretele gingival și cel parapulpar pentru a facilita refularea cimentului."},{"id":"D","text":"Realizarea peretelui gingival perpendicular pe axul lung (unghi de 90°) sau cu o ușoară înclinare spre peretele parapulpar (unghi ascuțit)."},{"id":"E","text":"Prepararea cavității orizontale sub formă de coadă de rândunică."}],"correct":["A","D","E"],"pages":[64],"source":"set-2"},{"id":"set2-HYx0LDrS","fingerprint":"c47315c29d9af51d","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt afirmațiile valabile referitoare la asigurarea formei de rezistență pentru o cavitate de clasa I?","options":[{"id":"A","text":"Materialul de restaurare trebuie să aibă o grosime de 1,5-2 mm pentru a rezista la forțele ocluzale."},{"id":"B","text":"Peretele pulpar al cavităților ocluzale se prepară în dentină sănătoasă, la 0,5-1 mm de joncțiunea amelo-dentinară."},{"id":"C","text":"Lățimea vestibulo-orală a preparației trebuie să reprezinte 1/4 din distanța măsurată între vârful cuspidului vestibular și cel oral."},{"id":"D","text":"Un unghi mai mic de 90° între peretele de smalț și suprafața externă a dintelui conferă o rezistență maximă la fracturi."},{"id":"E","text":"Pereții de smalț trebuie să formeze un unghi de 90°-110° în raport cu suprafața externă a dintelui."}],"correct":["A","B","E"],"pages":[65],"source":"set-2"},{"id":"set2-3ZAmDxjj","fingerprint":"6ff3faf80ea2ce0c","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt elementele ce descriu corect asigurarea rezistenței pentru cavitățile de clasa a II-a și a III-a?","options":[{"id":"A","text":"Grosimea materialului de restaurare la cavitățile de clasa a III-a trebuie să fie de minimum 1-1,5 mm."},{"id":"B","text":"Zona de întâlnire între cavitatea orizontală și cea verticală la clasa a II-a poartă denumirea de istm și trebuie menținută sub formă de unghi ascuțit."},{"id":"C","text":"La cavitatea de clasa a II-a, cavitatea orizontală este preparată exclusiv pentru retenție, nepunând probleme majore de rezistență."},{"id":"D","text":"La cavitatea de clasa a III-a se pot face concesii privind rezistența, permițându-se păstrarea unghiului incizal subminat."},{"id":"E","text":"Cavitatea de retenție orizontală la clasa a II-a necesită dimensiuni vestibulo-orale de cel puțin 1/3 din distanța intercuspidiană."}],"correct":["A","C","D"],"pages":[65],"source":"set-2"},{"id":"set2-NAVkcVX8","fingerprint":"efc16b63ce3920fb","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Care sunt afirmațiile exacte referitoare la etapa de finisare a marginilor cavității?","options":[{"id":"A","text":"La cavitatea verticală de clasa a II-a se realizează netezirea marginilor pereților vestibular și oral și bizotarea pragului gingival."},{"id":"B","text":"La cavitatea de clasa I, prismele de smalț trebuie finisate asfel încât să formeze o zonă marginală retentivă la limita cu materialul de restaurare."},{"id":"C","text":"Pentru cavitatea de clasa I, unghiul ideal format de marginile de smalț în etapa de finisare este de 90-110º."},{"id":"D","text":"La cavitățile de clasa a III-a, a IV-a și a V-a, finisarea constă în realizarea unor margini netede, cu linii curbe și fără anfractuozități."},{"id":"E","text":"La cavitățile de clasa a III-a, a IV-a și a V-a se evită bizotarea marginilor de smalț atunci când se utilizează materiale aderente."}],"correct":["A","C","D"],"pages":[66],"source":"set-2"},{"id":"set2--GQCpgGf","fingerprint":"bb9a074514c555a4","chapterId":"set-2","subchapterId":"set2-1.06","type":"CS","text":"Care sunt dimensiunile recomandate pentru lățimea vestibulo-orală a preparației și pentru adâncimea peretelui pulpar față de joncțiunea amelo-dentinară în cazul unei cavități de clasa I?","options":[{"id":"A","text":"1/3 din distanța dintre cuspidul vestibular și cel oral; 1,5-2 mm față de joncțiunea amelo-dentinară."},{"id":"B","text":"1/2 din distanța dintre cuspidul vestibular și cel oral; 0,5-1 mm față de joncțiunea amelo-dentinară."},{"id":"C","text":"1/3 din distanța dintre cuspidul vestibular și cel oral; 0,5-1 mm față de joncțiunea amelo-dentinară."},{"id":"D","text":"1/4 din distanța dintre cuspidul vestibular și cel oral; 1,5-2 mm față de joncțiunea amelo-dentinară."},{"id":"E","text":"1/4 din distanța dintre cuspidul vestibular și cel oral; 0,5-1 mm față de joncțiunea amelo-dentinară."}],"correct":["C"],"pages":[65],"source":"set-2"},{"id":"set2-CQQmjB1v","fingerprint":"05f210d7af608cee","chapterId":"set-2","subchapterId":"set2-1.06","type":"CM","text":"Prin ce modalități specifice se asigură rezistența la nivelul cavităților de clasa a II-a și a III-a?","options":[{"id":"A","text":"La cavitatea verticală de clasa a II-a, rezistența se realizează prin scurtarea din înălțime a pereților vestibular sau oral constituiți numai din smalț."},{"id":"B","text":"La cavitatea de clasa a III-a este interzisă păstrarea unghiului incizal subminat, din cauza riscului iminent de fractură."},{"id":"C","text":"La cavitățile convenționale de clasa a III-a, se realizează unghiuri de 90° între peretele lateral al cavității și suprafața smalțului."},{"id":"D","text":"La cavitatea orizontală a clasei a II-a, pereții vestibulari și orali trebuie modelați divergent spre ocluzal pentru a spori rezistența la masticație."},{"id":"E","text":"Pentru creșterea rezistenței la cavitățile de clasa a II-a, cuspizii nesusținuți de dentină sănătoasă necesită căptușirea bolților cuspidiene."}],"correct":["A","C","E"],"pages":[65],"source":"set-2"}];
